-- Synthetic local database only. Never execute this file in production.
create schema auth; create schema storage;
create role authenticated; create role anon; create role driver_portal; create role service_role bypassrls;
grant usage on schema public,auth,storage to authenticated,anon,driver_portal;
create table auth.users(id uuid primary key,email text);
create or replace function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create or replace function auth.role() returns text language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claim.role',true),''),'anon')$$;
grant execute on function auth.uid(),auth.role() to public;
create table public.account_access(user_id uuid primary key references auth.users(id),display_name text,role text,status text);
create table public.driver_accounts(auth_user_id uuid,active boolean default true);
create or replace function public.is_account_active() returns boolean language sql stable security definer as $$select exists(select 1 from public.account_access where user_id=auth.uid() and status='active')$$;
create or replace function public.current_account_role() returns text language sql stable security definer as $$select role from public.account_access where user_id=auth.uid() and status='active'$$;
create or replace function public.is_office_account() returns boolean language sql stable security definer as $$select public.is_account_active() and not exists(select 1 from public.driver_accounts where auth_user_id=auth.uid() and active)$$;
create table public.vehicles(id uuid primary key default gen_random_uuid(),vehicle_reg text,vehicle_type text,vehicle_name text,active boolean default true);
create table public.drivers(id bigint generated by default as identity primary key,name text not null,vehicle_reg text default '',vehicle_model text,vehicle_type text,assigned_vehicle_id uuid references vehicles(id),active boolean default true,user_id uuid,created_at timestamptz default now());
create table public.booking_diary(id bigint primary key,driver_id bigint references drivers(id),vehicle_id uuid references vehicles(id));
create table public.fuel_logs(id bigint primary key,vehicle_id uuid references vehicles(id));
create table public.trip_journeys(id bigint primary key,vehicle_id uuid references vehicles(id));
create table public.ees_hr_admins(user_id uuid primary key references auth.users(id),granted_at timestamptz default now());
create table public.ees_driver_vehicle_assignments(id uuid primary key default gen_random_uuid(),driver_id bigint references drivers(id),vehicle_id uuid references vehicles(id),effective_from date not null,effective_to date,assignment_kind text check(assignment_kind in ('permanent','temporary')),reason text,notes text,recorded_by uuid,recorded_at timestamptz default now(),previous_vehicle_reg text,check(effective_to is null or effective_to>=effective_from));
create table public.ees_hr_meetings(id uuid primary key default gen_random_uuid(),driver_id bigint not null references drivers(id),meeting_date date not null,category text check(category in ('general','performance','attendance','welfare','safety','disciplinary')),subject text not null,attendees text not null,discussion text not null,employee_response text,agreed_actions text,follow_up_date date,acknowledgement text default 'not_requested',created_by uuid not null,created_at timestamptz default now());
create table storage.buckets(id text primary key,name text,public boolean default false,file_size_limit bigint,allowed_mime_types text[]);
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text references storage.buckets(id),name text not null,unique(bucket_id,name));
alter table storage.objects enable row level security;
grant select,insert,update,delete on storage.objects to authenticated;
-- A permissive legacy policy deliberately tests the new restrictive bucket guard.
create policy fixture_legacy_storage_access on storage.objects for all to authenticated using(true) with check(true);
create or replace function public.ees_change_driver_vehicle(p_driver_id bigint,p_vehicle_id uuid,p_effective_from date,p_assignment_kind text,p_reason text,p_notes text default null,p_effective_to date default null) returns void language plpgsql as $$begin raise exception 'legacy fixture function must be replaced';end$$;
